import std.thread
class Log:
    lines: Array[String] = []
unsafe extern "C":
    @safety("`cb` and `ud` are a pair `on_main` was given")
    unsafe fn off_main(cb: extern "C" fn(*mut void), ud: *mut void)
    @ffi(param(cb, callback(retained, user_data=ud), threads(main)), destroys(off_main))
    safe fn on_main(cb: extern "C" fn(*mut void), ud: *mut void)   # the host runs it on its main thread
    @ffi(no_callbacks)
    safe fn block_forever()
fn worker():
    log = shares mut Log()                                            # a one-thread owner of the worker thread
    token = on_main(fn() owns log: log.lines.push(owns String("tick")))   # line 13 BREAKS: accepted (`shares mut` under threads(main)); the main thread will push to the worker's list
    log.lines.push(owns String("mine"))                               # line 14: the worker writes the same list: a data race, and two threads move one plain count
    block_forever()
fn main():
    h = thread.spawn(owns fn(): worker())
    h.join()

