import std.thread
unsafe extern "C":
    @ffi(destroys(ctx_free))
    type Ctx                                             # nothing is reachable from it: [THR-8]/[THR-9] infer `Send` and `ThreadShared`
    @safety("`c` is a context C made, not freed yet")
    unsafe fn ctx_free(c: *mut Ctx)
    @ffi(result(returns_owned(destructor=ctx_free), one))
    safe fn ctx_new() -> owns Ctx
    @ffi(effects=[], no_callbacks, param(c, borrowed, one))
    safe fn ctx_lookup(c: Ctx, k: c_int) -> c_int         # C: `int ctx_lookup(const Ctx* c, int k)`, which fills a cache inside `*c` on a miss
fn main():
    ctx = ctx_new()
    with thread.scope() as s:
        s.spawn(fn(): println(ctx_lookup(ctx, 1)))        # line 14 BREAKS: two tasks hold a `ref Ctx` at once, allowed since `Ctx` is `ThreadShared`
        s.spawn(fn(): println(ctx_lookup(ctx, 2)))        # line 15: C writes its cache from both threads

